    if (library == null || today == null || bookTitle == null || bookTitle.length() == 0)
    {
      return false;
    }

    Document matchedDocument = null;
    for (Document document : library.getDocuments())
    {
      if (bookTitle.equals(document.getTitle()))
      {
        matchedDocument = document;
        break;
      }
    }

    if (!(matchedDocument instanceof Book))
    {
      return false;
    }

    Book book = (Book)matchedDocument;

    for (Member member : library.getMembers())
    {
      for (BorrowRecord record : member.getBorrowRecords())
      {
        if (record.getBook() == book)
        {
          return false;
        }
      }
    }

    int activeBorrowCount = 0;
    for (BorrowRecord record : getBorrowRecords())
    {
      if (record.getBook() != null)
      {
        activeBorrowCount++;
      }
    }

    if (activeBorrowCount >= 3)
    {
      return false;
    }

    BorrowRecord borrowRecord = MunicipalLibraryFactory.eINSTANCE.createBorrowRecord();
    borrowRecord.setBorrowingDate(today);
    borrowRecord.setReturnDue(new Date(today.getTime() + 7L * 24L * 60L * 60L * 1000L));
    borrowRecord.setBook(book);
    getBorrowRecords().add(borrowRecord);
    return true;
    
